function renderVisualChart(){
 const host=$('#visual-chart');if(!host)return;if(exploreMode==='solar'){const solar=solarDraft()||S.b.energy?.solar;if(!solar?.production||solar.production.key!==EnterpriseEnergy.providerKey(solar.config)){host.innerHTML='<h3>Tu techo, listo para comparar</h3><p>La cantidad es una vista previa. Calcula la generación con la ubicación del edificio para estimar la compra a la red.</p><button class="small" data-act="sec" data-sec="solar">Calcular mi escenario</button>';return;}try{const d=EnterpriseEnergyUI.demand(S.b,solar.config),st=savingsState(S.b),usage=st.revision===S.b.revision?EnterpriseSavings.simulate(S.b,st.reductions):null,effective={...solar.config,reduction:solar.config.demandSource==='inventory'&&usage?.saving>0&&d.adjustable>0?usage.saving/d.adjustable*100:0},r=EnterpriseEnergy.simulate(effective,solar.production,d.months,S.b.budget?.tariffRate??null,d.adjustable,d.options),combined=r.scenarios[3],unit=r.monthCount===12?'kWh / año simulado':'kWh / '+r.monthCount+' meses';host.innerHTML='<h3>Lo que cambia con tu techo solar</h3>'+bars([{label:'Demanda del edificio',value:combined.total.load},{label:'Generación solar',value:combined.total.pv},{label:'Compra a la red',value:combined.total.import}],{unit})+'<p class="hint">Balance aproximado según el consumo del edificio y la referencia solar. '+esc(d.origin)+'</p>';return;}catch(e){host.innerHTML='<p>'+esc(e.message)+'</p>';return;}}const f=floorOf(S.nav.floorId),s=S.nav.level==='space'&&S.nav.spaceId&&spaceOf(S.nav.spaceId),items=S.nav.level==='building'?S.b.floors.map(f=>({id:f.id,label:f.name,value:known(f.totals)})):s?s.equipment.map(e=>({id:e.id,label:e.name,value:e.calc.kwh})):f?.spaces.map(s=>({id:s.id,label:s.name,value:known(s.totals)}))||[];
 host.innerHTML=`<div class="row between"><div><span class="eyebrow">DÓNDE SE CONCENTRA LA ENERGÍA</span><h3>${s?'Equipos de '+esc(s.name):f&&S.nav.level!=='building'?'Espacios de '+esc(f.name):'Consumo por piso'}</h3></div><span class="badge">kWh / mes típico</span></div>${bars(items,{act:S.nav.level==='building'?'enter-floor':s?'select-eq':'enter-space-id'})}<p class="hint">Estimación por inventario · sin datos no significa cero. Las partículas ilustran intensidad relativa, no flujo eléctrico real.${reduced()?' Movimiento reducido: efectos estáticos.':''}</p>`;
}
document.addEventListener('change',e=>{if(e.target.id==='visual-quality'){S.opts.quality=e.target.value;try{localStorage.setItem('kwh-org-visual-v1',JSON.stringify({particles:S.opts.particles,quality:S.opts.quality}));}catch{}refresh();}});
