async function api(path,{method='GET',body}={}){
 if(S.sandbox)return sandboxRequest(path,method,body||{});
 try{return await EnterpriseTransport.request('/api/org'+path,{method,body,csrf:S.csrf});}
 catch(error){if(error.status===401){const banner=$('#connection-banner');if(banner){banner.hidden=false;banner.querySelector('span').textContent='Tu sesión terminó. Conserva tus cambios y vuelve a iniciar sesión antes de guardar.';}}throw error;}
}
function confirmedBuilding(data,id){const b=data?.building;if(!b||b.id!==id||!Number.isSafeInteger(b.revision)||!Array.isArray(b.floors)||!Array.isArray(b.records)){const e=new Error('No se pudo confirmar el resultado del guardado. Consulta el estado actual antes de volver a guardar; la solicitud no se ha repetido.');e.code='WRITE_UNCERTAIN';throw e;}return b;}
async function change(path,method,body={}){
 if(S.readOnly)throw new Error('La demostración sin cuenta es de solo lectura.');
 const buildingId=S.b.id,revision=S.b.revision;
 try{const d=await api(path,{method,body:{...body,revision}});if(d.deleted===true&&method==='DELETE'&&path==='/buildings/'+buildingId){S.full.delete(buildingId);S.list=S.list.filter(x=>x.id!==buildingId);if(S.activeId===buildingId){S.activeId=null;S.b=null;await loadAll();S.nav={level:'building',floorId:null,spaceId:null,equipId:null};return go('resumen');}return d;}setBuilding(confirmedBuilding(d,buildingId));return d;}
 catch(e){if(e.code==='REVISION_CONFLICT'){try{setBuilding((await api('/buildings/'+buildingId)).building);e.message+=' Se cargó la versión actual.';}catch{e.message+=' No se pudo cargar la versión actual; vuelve a abrir el edificio.';}}throw e;}
}

