function legendHtml(fixedMax){
 const max=fixedMax??(S.maxes[0]||0),step=max/5;
 if(!max)return '<span class="mute">Aún no hay consumo estimado que colorear: agrega equipos con potencia y horario. Los espacios sin datos se muestran en gris con rayas.</span>';
 return '<span>Escala de consumo por espacio (kWh/mes, igual en todos los pisos del edificio):</span>'+SCALE.map((c,i)=>`<span><i style="background:${c}"></i>${nf.format(step*i)}–${nf.format(step*(i+1))}</span>`).join('')+'<span><i class="hatch"></i>Sin datos</span><span class="mute" style="flex-basis:100%">El número de cada etiqueta es el valor real; el color es solo orientativo. Los equipos dibujados salen de tu inventario (ubicación esquemática); el mobiliario no cuenta como consumo.</span>';
}
function webglData(b=S.b,fixedMax){
 const max=fixedMax??Math.max(0,...b.floors.flatMap(f=>f.spaces.map(s=>s.totals.kwh)));if(b===S.b)S.maxes=[max];
 const equipment={};for(const f of b.floors)for(const s of f.spaces)equipment[s.id]=s.equipment.map(e=>({id:e.id,name:e.name,category:e.category,quantity:e.quantity,placement:S.placementPreview?.id===e.id?S.placementPreview.position:e.placement||null,kwh:e.calc?.kwh??null,active:e.active!==false}));
 return {solar:(solarDraft(b)||b.energy?.solar)?.config||null,equipment,floors:b.floors.map((f,i)=>({id:f.id,kwh:known(f.totals),order:f.order??i,config:f.config||null,circulation:f.circulation||null,name:f.name,label:`${f.name} · ${f.totals.knownItems?fmt(f.totals.kwh):'sin datos'}${f.totals.unknownItems?' · incompleto':''}`,spaces:f.spaces.map(s=>{const p=s.noOwnEquipment?{color:rgb(SCALE[0]),hatch:false,sub:'sin equipos propios'}:paint(s.totals,max);return {id:s.id,kwh:s.noOwnEquipment?0:known(s.totals),name:s.name,slot:s.slot,kind:s.kind,workstations:s.workstations,occupied:s.occupied,deskMode:s.deskMode,plan:s.plan||null,hatch:p.hatch,color:p.hatch?null:hex(p.color),text:`${s.name} · ${p.sub}`};})}))};
}
function ensureViewer(){
 const body=$('#stage-body'),want=(!S.view3d||(exploreMode==='solar'&&!S.webglOk))?null:(S.webglOk&&window.KwhGlb?'webgl':'canvas');
 if(S.viewer&&S.kind!==want){S.viewer.destroy();S.viewer=null;body.innerHTML='';}
 S.kind=want;if(!want||S.viewer)return;
 if(want==='webgl'){
  body.innerHTML='<div id="glb-host" class="glb-host"><p class="mute glb-loading">Cargando modelo 3D…</p></div>';
  S.viewer=KwhGlb.create($('#glb-host'),{url:'/models/KWH-Empresarial.glb',
   onSelect:onPick,
   onInteract:()=>tourPause('Pausado: estás explorando la escena.'),
   onReady:()=>{const l=document.querySelector('.glb-loading');l&&l.remove();pushWebgl();},
   onFail:e=>{S.webglOk=false;S.webglError=e&&e.message?String(e.message).slice(0,120):'WebGL no disponible';if(S.viewer){S.viewer.destroy();S.viewer=null;}S.kind=null;if(S.sec==='edificios')refresh();}});
  if(!S.viewer){S.webglOk=false;S.webglError='WebGL no disponible en este navegador';S.kind=null;return ensureViewer();}
  pushWebgl();return;
 }
 body.innerHTML='<canvas tabindex="0" role="img" aria-label="Vista esquemática (sin WebGL). Flechas para rotar, más y menos para acercar; usa la estructura para navegar."></canvas>';const cv=body.querySelector('canvas');
 S.viewer=Enterprise3D.create(cv,{onSelect:onPick,onHover:(id,e)=>{const t=$('#tip');if(!id){t.hidden=true;return;}t.innerHTML=tipText(id);t.hidden=false;const r=$('.stage').getBoundingClientRect();t.style.left=Math.min(r.width-250,Math.max(4,e.clientX-r.left+12))+'px';t.style.top=Math.max(4,e.clientY-r.top+12)+'px';}});
 if(!S.viewer){S.view3d=false;body.innerHTML='';}
}
function pushWebgl(){
 if(!S.viewer||S.kind!=='webgl'||!S.b)return;const n=S.nav;
 S.viewer.setData(webglData());S.viewer.setView({roofMode:exploreMode==='solar',level:n.level,floorId:n.floorId,spaceId:n.spaceId,equipId:n.equipId,isolate:S.opts.isolate,explode:S.opts.explode,layer:S.opts.layer,focus:S.focus,equipCat:S.equipCat,doors:S.opts.doors,particles:S.opts.particles,quality:S.opts.quality,preset:S.opts.preset});
}
/* Vista de respaldo (Canvas 2D esquemático) */
function scene(){
 const b=S.b,n=S.nav,out=[];
 if(n.level==='building'){const max=Math.max(0,...b.floors.map(f=>f.totals.kwh));S.maxes=[max];
  b.floors.forEach((f,i)=>{const p=paint(f.totals,max);out.push({id:'f'+f.id,x:0,y:0,z:i*1.12+(n.floorId===f.id?1.4:0),w:6,d:4,h:1,color:p.color,hatch:p.hatch,windows:true,label:f.name,sub:p.sub,labelAt:'right',alpha:n.floorId&&n.floorId!==f.id?.55:1});});
 }else{const f=floorOf(n.floorId);
  if(n.level==='floor'){const max=Math.max(0,...f.spaces.map(s=>s.totals.kwh));S.maxes=[max];out.push({id:'f'+f.id,x:0,y:0,z:0,w:8,d:6,h:.3,color:[225,225,215],selectable:false});
   const c=Math.ceil(Math.sqrt(f.spaces.length||1)),r=Math.ceil(f.spaces.length/c||1),cw=7.4/c,cd=5.4/r;
   f.spaces.forEach((s,i)=>{const p=paint(s.totals,max);out.push({id:'s'+s.id,x:.3+(i%c)*cw+.1,y:.3+Math.floor(i/c)*cd+.1,z:.3,w:cw-.2,d:cd-.2,h:n.spaceId===s.id?.9:.6,color:p.color,hatch:p.hatch,label:s.name,sub:s.kind+' · '+p.sub,alpha:n.spaceId&&n.spaceId!==s.id?.6:1});});
  }else{const s=spaceOf(n.spaceId),max=Math.max(0,...s.equipment.map(e=>e.calc.kwh||0));S.maxes=[max];const p=paint(s.totals,s.totals.kwh);
   out.push({id:'s'+s.id,x:0,y:0,z:0,w:8,d:6,h:.3,color:p.color,selectable:false,label:s.name,sub:s.kind,labelAt:'right'});
   const c=Math.ceil(Math.sqrt(s.equipment.length||1));
   s.equipment.forEach((e,i)=>{const q=.8+.25*Math.min(Math.sqrt(e.quantity),3),pe=paint({knownItems:e.calc.kwh!=null?1:0,kwh:e.calc.kwh||0,unknownItems:0},max);
    out.push({id:'e'+e.id,x:.5+(i%c)*(7/c)+.2,y:.5+Math.floor(i/c)*(5/Math.ceil(s.equipment.length/c))+.2,z:.3,w:q,d:q,h:.5,color:pe.color,hatch:pe.hatch,icon:e.category,label:e.name,sub:`${e.quantity} unidad${e.quantity>1?'es':''}`,badge:pe.sub,alpha:n.equipId&&n.equipId!==e.id?.6:1});});}}
 return out;
}
function tipText(raw){
 const t=raw[0],id=Number(raw.slice(1));let name,kw,extra;
 if(t==='e'){const e=equipOf(id);if(!e)return '';name=e.name;kw=e.calc.kwh;extra=`${e.quantity} unidad(es)`;}
 else{const x=t==='f'?floorOf(id):spaceOf(id);if(!x)return '';name=x.name;kw=known(x.totals);extra=S.b.isDemo?'demostración':'estimación por inventario';}
 return `<strong>${esc(name)}</strong><br>${esc(fmt(kw))}<br><span class="mute">${esc(extra)}</span>`;
}
function onPick(raw){
 if(raw.startsWith('f')&&exploreMode==='solar')exploreMode='rooms';
 if(raw==='pv')return go('solar');
 if(raw.startsWith('corr')){exploreMode='corridors';S.nav={level:'floor',floorId:Number(raw.slice(4)),spaceId:null,equipId:null};return refresh();}
 tourPause('Pausado: seleccionaste un elemento.');
 const t=raw[0],id=Number(raw.slice(1)),n=S.nav;
 if(t==='f'&&n.level==='building')Object.assign(n,{floorId:id,spaceId:null,equipId:null});
 else if(t==='s'&&n.level!=='building'){n.spaceId=id;n.equipId=null;}
 else if(t==='e'&&n.level==='space')n.equipId=id;
 else return;
 refresh();const nm=t==='f'?floorOf(id)?.name:t==='s'?spaceOf(id)?.name:equipOf(id)?.name;say('Seleccionado: '+nm);
}
