 $('#view-context').innerHTML=`<div><span class="eyebrow">${exploreMode==='solar'?'TECHO SOLAR':n.level==='building'?'VISTA GENERAL':n.level==='floor'?'INTERIOR DEL PISO':'DETALLE DEL ESPACIO'}</span><strong>${esc(n.level==='building'?b.name:n.level==='space'?spaceOf(n.spaceId)?.name:active?.name||'')}</strong></div><div class="row">${n.level==='building'&&active?`<button class="primary" data-act="enter-floor" data-id="${active.id}">Ver interior de ${esc(active.name)} →</button>`:n.level!=='building'?'<button class="small" data-act="to-building">← Ver edificio</button>':''}</div>`;
 $('#floors-sel').innerHTML=b.floors.map(f=>`<div class="f"><button class="small" data-act="select-floor" data-id="${f.id}" ${n.floorId===f.id?'aria-current="true"':''}>${esc(f.name)}</button><button class="small" data-act="enter-floor" data-id="${f.id}" aria-label="Abrir ${esc(f.name)}" title="Abrir piso (ver interior)">Ver interior</button></div>`).join('')||'<span class="mute">Sin pisos</span>';if(!S.readOnly)$('#floors-sel').insertAdjacentHTML('beforeend','<button type="button" class="small floor-add-shortcut" data-act="add-floor">Añadir piso</button>');
